// This code has been fully generated by an AI.
//
// Pure helpers for the statistics charts. No DOM access, so the module can be
// tested with node --test.

export const METRICS = {
  km: { label: "Distanz", unit: "km", digits: 1 },
  hours: { label: "Zeit", unit: "h", digits: 1 },
  ascent: { label: "Höhenmeter", unit: "Hm", digits: 0 },
};

/** Series for the bar chart: x = bucket index, y = values of the metric. */
export function barSeries(data, metric) {
  const values = data[metric] ?? data.km;
  return { x: values.map((_, i) => i), y: values };
}

/**
 * Shows every n-th category label so labels keep at least minPx apart
 * (53 week labels do not fit on narrow screens).
 */
export function labelStep(count, widthPx, minPx = 42) {
  if (count <= 0 || widthPx <= 0) return 1;
  return Math.max(1, Math.ceil((count * minPx) / widthPx));
}

/** Sum of a metric over all buckets. */
export function total(data, metric) {
  return (data[metric] ?? []).reduce((a, b) => a + b, 0);
}

/**
 * Data for the cumulative chart: x = day of year (1-based), one series per
 * year (padded to 366 days with null) and an optional linear goal line.
 */
export function cumulativeSeries(data) {
  const days = 366;
  const x = Array.from({ length: days }, (_, i) => i + 1);
  const series = data.years.map((y) => ({
    label: String(y.year),
    values: x.map((d) => y.km[d - 1] ?? null),
  }));
  if (data.goal > 0) {
    const n = data.daysInYear || 365;
    series.push({ label: `Ziel ${data.goal} km`, goal: true, values: x.map((d) => (d <= n ? Math.round((data.goal * d) / n) : null)) });
  }
  return { x, series };
}

const MONTH_STARTS = [1, 32, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335];
const MONTHS = ["Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"];

/** Axis ticks for day-of-year: first day of each month (non-leap year). */
export function monthTicks() {
  return { values: MONTH_STARTS, labels: MONTHS };
}

/** Colors for year lines: selected year strongest, older years lighter. */
export function yearColor(index) {
  const palette = ["#e8590c", "#1c7ed6", "#2b8a3e", "#7048e8", "#868e96"];
  return palette[index % palette.length];
}

/**
 * Index of the day the cumulative legend shows without cursor: the last
 * day with data of the first (selected) series, i.e. today in the current
 * year and 31 Dec in past years. Comparing all years on that day answers
 * "where was I at this point in earlier years?". -1 without data.
 */
export function referenceIndex(series) {
  const values = series[0]?.values ?? [];
  for (let i = values.length - 1; i >= 0; i--) {
    if (values[i] != null) return i;
  }
  return -1;
}
